// Lecture seule. Parametres : jour (AAAA-MM-JJ) et immat (defaut FL 192 RP, camion blanc).
let q = {};
try { q = $('Parametres (jour, immat)').first().json.query || {}; } catch (e) {}
const JOUR = q.jour || DateTime.now().setZone('Europe/Paris').toFormat('yyyy-MM-dd');
const IMMAT = q.immat || 'FL 192 RP';
const r = $input.first().json || {};
const b = r.body || {};
const d = b.Data || b.data || {};
const tok = d.AccessToken || d.accessToken;
if (!tok) return [{ json: { erreur: 'Connexion Quartix refusee', code: r.statusCode || null } }];
const base = 'https://qws.quartix.net/v2/api';
const H = { AccessToken: tok };
const get = async (p) => { const x = await this.helpers.httpRequest({ method: 'GET', url: base + p, headers: H, json: true, timeout: 20000 }); return (x && (x.Data || x.data)) || []; };
const vehicules = await get('/vehicles');
const v = vehicules.find(x => String(x.RegistrationNumber).replace(/\s/g, '') === String(IMMAT).replace(/\s/g, ''));
if (!v) return [{ json: { erreur: 'Vehicule introuvable', immats: vehicules.map(x => x.RegistrationNumber) } }];
const lieu = s => String(s || '').replace(/, France$/, '').trim();
const estDepot = s => /^climatpro$/i.test(String(s || '').trim()) || /Chem(in|\.) de Dandon/i.test(String(s || ''));
const hm = iso => iso ? DateTime.fromISO(iso).setZone('Europe/Paris').toFormat('HH:mm') : null;
const T = (await get('/vehicles/trips?StartDay=' + JOUR + '&EndDay=' + JOUR)).filter(t => t.VehicleID === v.VehicleId).sort((a, b) => String(a.StartDateTime).localeCompare(String(b.StartDateTime)));
const arrets = [];
for (let i = 0; i < T.length; i++) {
  const arr = T[i], dep = T[i + 1];
  if (!dep) continue;
  const min = Math.round((Date.parse(dep.StartDateTime) - Date.parse(arr.EndDateTime)) / 60000);
  if (min < 5 || estDepot(arr.EndLocation)) continue;
  arrets.push({ lieu: lieu(arr.EndLocation), arrivee: hm(arr.EndDateTime), depart: hm(dep.StartDateTime), minutes: min, duree: Math.floor(min / 60) + 'h' + String(min % 60).padStart(2, '0') });
}
const parLieu = {};
for (const a of arrets) parLieu[a.lieu] = (parLieu[a.lieu] || 0) + a.minutes;
const totaux = Object.entries(parLieu).map(([l, m]) => ({ lieu: l, minutes: m, duree: Math.floor(m / 60) + 'h' + String(m % 60).padStart(2, '0') })).sort((a, b) => b.minutes - a.minutes);
return [{ json: { jour: JOUR, immat: v.RegistrationNumber, arrets, totauxParLieu: totaux, trajets: T.map(t => ({ depart: hm(t.StartDateTime), de: lieu(t.StartLocation), arrivee: hm(t.EndDateTime), a: lieu(t.EndLocation), km: t.Distance })) } }];
